function assertCloneable(value, topLevel) {
  if (value === undefined) {
    if (topLevel) throw new TypeError();
    return;
  }
  if (value === DELETE) {
    if (topLevel) throw new TypeError();
    return;
  }
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError();
    return;
  }
  if (typeof value === 'function' || typeof value === 'symbol') throw new TypeError();
  if (Array.isArray(value)) {
    for (const element of value) assertCloneable(element, false);
    return;
  }
  if (isRecord(value)) {
    for (const key of Object.keys(value)) {
      const prop = value[key];
      if (prop === undefined || prop === DELETE) continue;
      assertCloneable(prop, false);
    }
    return;
  }
  throw new TypeError();
}

function cloneInner(value) {
  if (value === null || typeof value !== 'object') return value;
  if (Array.isArray(value)) return value.map((element) => cloneInner(element));
  if (isRecord(value)) {
    const out = {};
    for (const key of Object.keys(value)) {
      const prop = value[key];
      if (prop === undefined || prop === DELETE) continue;
      out[key] = cloneInner(prop);
    }
    return out;
  }
  throw new TypeError();
}

export function cloneValue(value) {
  assertCloneable(value, true);
  return cloneInner(value);
}

