import { cloneValue } from './clone-value.mjs';

export const DELETE = Symbol('delete');

function isRecord(value) {
  return (
    value !== null &&
    typeof value === 'object' &&
    Object.prototype.toString.call(value) === '[object Object]'
  );
}

function validateLayerValue(value) {
  if (value === undefined || value === DELETE) return;
  if (value === null || typeof value === 'boolean' || typeof value === 'string') return;
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) throw new TypeError();
    return;
  }
  if (typeof value === 'function' || typeof value === 'symbol') throw new TypeError();
  if (Array.isArray(value)) {
    for (const element of value) {
      if (element === DELETE) throw new TypeError();
      validateLayerValue(element);
    }
    return;
  }
  if (isRecord(value)) {
    for (const key of Object.keys(value)) validateLayerValue(value[key]);
    return;
  }
  throw new TypeError();
}

function validateLayer(layer) {
  for (const key of Object.keys(layer)) validateLayerValue(layer[key]);
}

function mergeRecords(base, layer) {
  const out = cloneValue(base);
  for (const key of Object.keys(layer)) {
    const incoming = layer[key];
    if (incoming === undefined) continue;
    if (incoming === DELETE) {
      delete out[key];
      continue;
    }
    if (
      Object.prototype.hasOwnProperty.call(out, key) &&
      isRecord(out[key]) &&
      isRecord(incoming)
    ) {
      out[key] = mergeRecords(out[key], incoming);
    } else {
      out[key] = cloneValue(incoming);
    }
  }
  return out;
}

function applyLayer(target, layer) {
  const out = cloneValue(target);
  for (const key of Object.keys(layer)) {
    const incoming = layer[key];
    if (incoming === undefined) continue;
    if (incoming === DELETE) {
      delete out[key];
      continue;
    }
    if (
      Object.prototype.hasOwnProperty.call(out, key) &&
      isRecord(out[key]) &&
      isRecord(incoming)
    ) {
      out[key] = mergeRecords(out[key], incoming);
    } else {
      out[key] = cloneValue(incoming);
    }
  }
  return out;
}

export function mergeLayers(...layers) {
  let out = {};
  for (const layer of layers) {
    if (layer === undefined) continue;
    if (!isRecord(layer)) throw new TypeError();
    validateLayer(layer);
    out = applyLayer(out, layer);
  }
  return out;
}

