import assert from 'node:assert/strict';
import { mergeLayers } from '../src/merge-layers.mjs';
test('later scalar values replace earlier values',()=>assert.deepEqual(mergeLayers({a:1},{a:2,b:false}),{a:2,b:false}));
test('nested objects merge without losing earlier keys',()=>assert.deepEqual(mergeLayers({db:{host:'h',port:1}},{db:{port:2}}),{db:{host:'h',port:2}}));
